(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  const cards = [...document.querySelectorAll('.tb-project-main')];
  (cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0]).click();
  await sleep(3200);
  let captured = null;
  const orig = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (b) => { captured = b; return orig(b); };
  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('分享作品'))?.click();
  await sleep(1500);
  [...document.querySelectorAll('.sw-btn')].find((b) => b.textContent.includes('生成分享页'))?.click();
  await sleep(4000);
  URL.createObjectURL = orig;
  const html = captured ? await captured.text() : '';
  out.totalBytes = html.length;
  const m = html.match(/var ECP = ("[A-Za-z0-9+/=]{100,}"|null);/);
  out.ecpVarFound = !!m;
  out.ecpEmbedded = !!m && m[1] !== 'null';
  if (out.ecpEmbedded) {
    const b64 = m[1].slice(1, -1);
    out.b64Len = b64.length;
    try {
      const bin = atob(b64);
      out.zipBytes = bin.length;
      out.isZip = bin.slice(0, 2) === 'PK';
      out.hasManifest = bin.includes('manifest.json');
      out.hasProjectName = bin.includes(new TextDecoder().decode(new TextEncoder().encode('循迹小车')));
      out.leaksCredential = /sk-[A-Za-z0-9]{6,}|api[_-]?key|ai_config/i.test(bin);
    } catch (e) { out.decodeError = String(e); }
  }
  const doc = new DOMParser().parseFromString(html, 'text/html');
  out.pageText = (doc.body?.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 120);
  return JSON.stringify(out);
})()
